// Type declarations for the xljs runtime.
// Generated by `xljs init`; keep next to your scripts for editor completion.

export {};

declare global {
  // ------------------------------------------------------------------ xljs

  interface Xljs {
    /** xljs のバージョン */
    readonly version: string;
    /** スクリプトに渡された引数（埋め込み exe ではドロップしたファイルのパスなど） */
    readonly args: string[];
    /** 実行中のスクリプト（埋め込み exe では exe と同じフォルダの仮想パス）の絶対パス */
    readonly script: string;
    /** スクリプトのあるフォルダ */
    readonly scriptDir: string;
    /** "windows" / "linux" / "darwin" */
    readonly platform: string;
    /** このコンピューターの名前（%COMPUTERNAME% と同じ。AD がなくても使える） */
    readonly computerName: string;
    /** スクリプトを実行しているユーザーのログオン名（ドメイン名なし。%USERNAME% と同じ） */
    readonly userName: string;
    /** 使用中の UI: "native" / "console" / "mock" */
    readonly ui: string;
    /** ダイアログのタイトル（既定はスクリプト名） */
    title: string;
    /** 終了コードを指定してスクリプトを終了する */
    exit(code?: number): never;
    /** 環境変数を取得（未定義なら null） */
    env(name: string): string | null;
    /** console.log と同じ形式で値を文字列化する */
    inspect(value: unknown, options?: { depth?: number }): string;
    /**
     * HTML 文書を PDF に書き出す（WebView2 が必要。Windows のネイティブ UI のみ）。HTML 内のスクリプトは動かない。
     * 画像は data: URL で埋め込む。改ページは CSS の break-before / break-after。書き出したファイルの絶対パスを返す
     */
    htmlToPdf(html: string, dest: PathLike, options?: HtmlPdfOptions): Promise<string>;
  }
  const xljs: Xljs;

  interface Console {
    log(...data: any[]): void;
    info(...data: any[]): void;
    debug(...data: any[]): void;
    warn(...data: any[]): void;
    error(...data: any[]): void;
    trace(...data: any[]): void;
    dir(item?: any, options?: { depth?: number }): void;
    table(data: any, columns?: string[]): void;
    assert(condition?: boolean, ...data: any[]): void;
    time(label?: string): void;
    timeLog(label?: string, ...data: any[]): void;
    timeEnd(label?: string): void;
    count(label?: string): void;
    countReset(label?: string): void;
    group(...data: any[]): void;
    groupCollapsed(...data: any[]): void;
    groupEnd(): void;
  }
  var console: Console;

  function setTimeout(handler: (...args: any[]) => void, timeout?: number, ...args: any[]): number;
  function setInterval(handler: (...args: any[]) => void, timeout?: number, ...args: any[]): number;
  function setImmediate(handler: (...args: any[]) => void, ...args: any[]): number;
  function clearTimeout(id?: number): void;
  function clearInterval(id?: number): void;
  function clearImmediate(id?: number): void;
  function queueMicrotask(callback: () => void): void;
  function structuredClone<T>(value: T): T;
  function atob(data: string): string;
  function btoa(data: string): string;

  class TextEncoder {
    readonly encoding: "utf-8";
    encode(input?: string): Uint8Array;
  }
  class TextDecoder {
    /** "utf-8", "shift_jis", "euc-jp", "utf-16le" など */
    constructor(label?: string, options?: { fatal?: boolean; ignoreBOM?: boolean });
    readonly encoding: string;
    decode(input?: ArrayBuffer | ArrayBufferView): string;
  }

  class DOMException extends Error {
    constructor(message?: string, name?: string);
  }
  /** xljs.exit と同じ */
  function exit(code?: number): never;
  /** 指定ミリ秒待つ */
  function sleep(ms: number): Promise<void>;

  // ------------------------------------------------------------------ dialogs

  function alert(message?: unknown): void;
  function confirm(message?: unknown): boolean;
  /** キャンセル時は null */
  function prompt(message?: unknown, defaultValue?: string): string | null;

  interface NotificationOptions {
    body?: string;
    tag?: string;
    data?: unknown;
  }
  /**
   * ブラウザの Notification。ui.notify と同じく画面右下に通知を出してすぐに戻る。
   * 許可は常に "granted"。クリックなどのイベントは発生しない
   */
  class Notification {
    constructor(title: string, options?: NotificationOptions);
    static readonly permission: "granted";
    static requestPermission(callback?: (permission: "granted") => void): Promise<"granted">;
    readonly title: string;
    readonly body: string;
    readonly tag: string;
    readonly data: unknown;
    onclick: ((this: Notification, ev: unknown) => unknown) | null;
    onclose: ((this: Notification, ev: unknown) => unknown) | null;
    onerror: ((this: Notification, ev: unknown) => unknown) | null;
    onshow: ((this: Notification, ev: unknown) => unknown) | null;
    /** 何もしない（通知は Windows が閉じる） */
    close(): void;
  }

  type WellKnownDirectory = "desktop" | "documents" | "downloads" | "music" | "pictures" | "videos";

  interface FilePickerAcceptType {
    description?: string;
    /** { "MIME": [".xlsx"] }、[".xlsx", ".xlsm"]、".csv" のいずれか */
    accept: Record<string, string | string[]> | string[] | string;
  }

  interface FilePickerOptions {
    types?: FilePickerAcceptType[];
    excludeAcceptAllOption?: boolean;
    startIn?: WellKnownDirectory | string | FileSystemHandle;
    /** ダイアログのタイトル（xljs 拡張） */
    title?: string;
    id?: string;
  }
  interface OpenFilePickerOptions extends FilePickerOptions {
    multiple?: boolean;
  }
  interface SaveFilePickerOptions extends FilePickerOptions {
    suggestedName?: string;
  }
  interface DirectoryPickerOptions {
    startIn?: WellKnownDirectory | string | FileSystemHandle;
    title?: string;
    id?: string;
    mode?: "read" | "readwrite";
  }

  /** ファイルを選択する。キャンセル時は空配列 */
  function showOpenFilePicker(options?: OpenFilePickerOptions): Promise<FileSystemFileHandle[]>;
  /** 保存先を選択する。キャンセル時は null。types を省略すると suggestedName の拡張子を種類と既定の拡張子にする */
  function showSaveFilePicker(options?: SaveFilePickerOptions): Promise<FileSystemFileHandle | null>;
  /** フォルダを選択する。キャンセル時は null */
  function showDirectoryPicker(options?: DirectoryPickerOptions): Promise<FileSystemDirectoryHandle | null>;

  // ------------------------------------------------------------------ ui

  interface ProgressOptions {
    title?: string;
    /** 総数。省略または 0 で総数不明（マーキー表示） */
    total?: number;
    message?: string;
    /** キャンセルボタンを出すか（既定 true） */
    cancellable?: boolean;
  }

  interface Progress {
    total: number;
    readonly done: number;
    message: string;
    /** ユーザーがキャンセル（またはコンソールで Ctrl+C）したか */
    readonly cancelled: boolean;
    /** 完了件数とメッセージを更新する */
    update(done: number, message?: string): this;
    /** 完了件数を 1 増やす */
    increment(message?: string): this;
    close(): void;
  }

  interface WithProgressOptions<T> extends ProgressOptions {
    /** 各要素の表示ラベル。既定はハンドルなら relativePath */
    label?: (item: T, index: number) => string;
    /**
     * キャンセルされたとき: "exit"（既定）はスクリプトを終了する（終了コード 1。フォームの ctx.withProgress では onSubmit を終える）。
     * "break" は反復を終えるだけ（続きの処理で ui.cancelled / ctx.cancelled を見る）
     */
    onCancel?: "exit" | "break";
  }

  interface Ui {
    alert: typeof alert;
    confirm: typeof confirm;
    prompt: typeof prompt;
    showOpenFilePicker: typeof showOpenFilePicker;
    showSaveFilePicker: typeof showSaveFilePicker;
    showDirectoryPicker: typeof showDirectoryPicker;
    /** 進捗表示を開く */
    progress(options?: ProgressOptions | string): Progress;
    /** 反復しながら進捗を表示する。キャンセルされるとスクリプトを終了する（onCancel: "break" なら反復が終わるだけ） */
    withProgress<T>(iterable: Iterable<T>, options?: WithProgressOptions<T> | string): Generator<T, void, undefined>;
    withProgress<T>(iterable: AsyncIterable<T>, options?: WithProgressOptions<T> | string): AsyncIterableIterator<T>;
    /**
     * 入力フォームを表示する。キャンセルされると null。
     * ネイティブ UI ではウィンドウ（WebView2）、コンソールでは対話入力になる。
     * onSubmit や buttons を指定すると、実行後もウィンドウを開いたまま進捗とログを表示し、
     * ウィンドウが閉じられたときに最後に送信された（検証を通った）値を返す。
     */
    form<V extends FormValues = FormValues>(options: FormOptions<V>): Promise<V | null>;
    /**
     * 表を表示する（並べ替え・絞り込み・列幅の変更・コピー・CSV/Excel に保存）。
     * selectable を指定すると OK/キャンセル付きになり、選んだ行（元のオブジェクト）を返す。キャンセルは []。
     */
    table<T>(rows: Iterable<T>, options: TableSelectOptions): Promise<T[]>;
    /** 表示のみ。ウィンドウを開いてすぐに戻る（閉じるまでプロセスは終了しない） */
    table<T>(rows: Iterable<T>, options?: TableOptions | string): TableView;
    /**
     * グラフ（AG Charts）やガントチャート（Frappe Gantt）をウィンドウに表示し、すぐに戻る（閉じるまでプロセスは終了しない）。
     * Excel のグラフ（sheet.charts の要素）もそのまま渡せる。
     * コンソール・mock ではグラフの元の行を表で出力する。options はウィンドウのタイトルの文字列か ChartWindowOptions
     */
    chart(spec: ChartSpec | ExcelChart, options?: ChartWindowOptions | string): ChartView;
    /** 直近の進捗表示がキャンセルされたか */
    readonly cancelled: boolean;
    /** エラーダイアログを表示する */
    error(message: unknown): void;
    /**
     * 画面右下に通知を出し、すぐに戻る（コンソールでは 1 行表示）。
     * options はタイトルの文字列か { title }（既定は xljs.title）。クリックすると xljs のウィンドウを前面に出す
     */
    notify(message: unknown, options?: string | { title?: string }): void;
    /**
     * 他のアプリで作業中に alert・confirm・prompt・ui.error・ピッカー・フォームなどが開いたとき、
     * 自動で通知を出すか（既定 true）
     */
    autoNotify: boolean;
  }
  const ui: Ui;

  // ------------------------------------------------------------------ ui.form

  type FormFieldType = "text" | "password" | "number" | "date" | "month" | "time" | "select" | "radio" |
    "checkbox" | "textarea" | "file" | "files" | "folder" | "saveFile" | "table" | "chart";

  /**
   * フォームの項目。値の型は type による:
   * text / password / textarea / select / radio は string、number は number | null、
   * date は Date | null（ローカル日付）、month は "YYYY-MM" | null、time は "HH:MM" | null、
   * checkbox は boolean、file / saveFile は FileSystemFileHandle | null、
   * files は FileSystemFileHandle[]、folder は FileSystemDirectoryHandle | null、
   * table は選択した行（元のオブジェクト）の配列（selectable: "single" なら行か null。selectable なしなら値なし。
   * 編集できる表で selectable なしならすべての行）、
   * chart は値なし（editable なガントチャートだけ、すべての行（編集が書き込まれた元のオブジェクト））
   */
  interface FormField {
    /** 値のキー */
    name: string;
    /** 表示名（既定は name） */
    label?: string;
    /** ラベルの前に出す Font Awesome のアイコン（"folder-open" は solid、"fa-regular fa-calendar" のようにクラスでも可） */
    icon?: string;
    /** 既定 "text" */
    type?: FormFieldType;
    /** 初期値。ファイル系はパスかハンドル、date は Date か "YYYY-MM-DD"、table は選択する行（行そのものか番号、配列可） */
    default?: unknown;
    /** 入力必須（checkbox はチェック必須、table は 1 行以上の選択が必須） */
    required?: boolean;
    /** select / radio の選択肢 */
    options?: (string | { value: string; label?: string })[];
    /** 入力欄が空のときの薄い表示。select では未選択の項目として表示し、初期値を未選択（""）にする */
    placeholder?: string;
    /** 入力欄の下に出す説明 */
    help?: string;
    /** マウスを重ねたときに出す説明（ツールチップ）。ラベルと入力欄に付く */
    tooltip?: string;
    /** number の範囲と刻み */
    min?: number;
    max?: number;
    step?: number | "any";
    /** textarea / files の行数。table では表示する行（ui.table の rows と同じ） */
    rows?: number | readonly unknown[];
    /** table の列（ui.table の columns と同じ。既定はオブジェクトのキー）。列ごとに編集の可否と検証を指定できる */
    columns?: (string | FormTableColumn)[];
    /** table で行を選べるようにする（クリックで選択。true は "multiple"） */
    selectable?: boolean | "single" | "multiple";
    /**
     * table のセルをその場で編集できるようにする（列の editable で個別に指定も可）。
     * 編集した値は検証を通ると元の行オブジェクトに直接書き込まれる。
     * エラーのあるセルは赤く表示され、エラーが残っていると送信できない
     */
    editable?: boolean;
    /**
     * table の行の検証（編集できる表）。行全体へのメッセージか { 列のキー: "メッセージ" } を返す。
     * 表示時と、行のセルが編集されるたびに呼ばれる
     */
    validateRow?(row: any, index: number): Record<string, string | null | undefined> | string | null | undefined | void |
      Promise<Record<string, string | null | undefined> | string | null | undefined | void>;
    /** table の表示する高さ（行数。既定は 8 行まで）。chart の高さ（1 行 25px として。既定 12） */
    height?: number;
    /** chart の項目のグラフ（ui.chart と同じ定義。ExcelChart も可）。ctx.chart(name, spec) で変えられる */
    chart?: ChartSpec | ExcelChart;
    /** ファイル系の拡張子（".xlsx" など）。ピッカーとドロップに使う */
    accept?: string | string[];
    /** 入力全体が一致すべき正規表現（文字列なら全体一致） */
    pattern?: string | RegExp;
    /** pattern に一致しないときのメッセージ */
    patternMessage?: string;
    /**
     * この項目の追加の検証。問題があればメッセージを返す（values はすべての項目の値）。
     * required などの検証が通ったあとに、入力欄を離れたとき（エラー表示中は入力のたび）と送信時に呼ばれる
     */
    validate?(value: any, values: FormValues): string | null | undefined | void | Promise<string | null | undefined | void>;
    /**
     * ユーザーが値を変えたときに呼ばれる（入力欄を離れたとき・Enter・選択・参照・ドロップ・table の行の選択）。
     * required などの検証と項目の validate が通ったときだけ呼ばれる（空欄にしたときも、必須でなければ呼ばれる）。
     * ctx.setValue でほかの項目を埋められる（例: 1 つ目のファイルと同じフォルダにある 2 つ目のファイルを自動で設定）。
     * setValue で変えた項目の onChange は呼ばれない。ここで起きたエラーはこの項目のエラーとして表示される
     * （コンソールでは呼び出し元に伝わる）。コンソール・mock では回答で変わった項目について項目の順に呼ばれる
     */
    onChange?(value: any, values: FormValues, ctx: FormChangeContext): unknown;
    /** remember: true のフォームで、この項目を保存しない場合は false（password は保存しない） */
    remember?: boolean;
  }

  /**
   * 項目のグループ。fields（タブの fields でも可）に項目と並べて書くと、見出しの下に項目をまとめて表示する。
   * 値は項目の name でほかの項目と同じオブジェクトにまとまる（グループの中にグループは入れられない）。
   * コンソールでは見出しを出してから順に尋ねる
   */
  interface FormGroup {
    /** 見出し */
    group: string;
    /** 見出しの前に出す Font Awesome のアイコン（FormField の icon と同じ） */
    icon?: string;
    /** 見出しの下に出す説明 */
    help?: string;
    fields: FormField[];
  }

  interface FormValues {
    [name: string]: any;
  }

  /** onSubmit の第 2 引数。ウィンドウ内の進捗・ログ表示 */
  interface FormContext {
    /** 中止ボタンが押された（またはウィンドウが閉じられた）か */
    readonly cancelled: boolean;
    /** 進捗を表示する。total を省略すると前回の総数（0 なら総数不明） */
    progress(done: number, total?: number, message?: string): void;
    progress(done: number, message: string): void;
    /** ログ欄に 1 行追加する */
    log(...args: unknown[]): void;
    /** ログ欄にエラーとして追加する */
    error(...args: unknown[]): void;
    /**
     * table の項目の行（と列）を入れ替える（選択は解除）。結果の一覧の表示などに使う。
     * コンソール・mock では表を出力する
     */
    table(name: string, rows: readonly unknown[], columns?: (string | FormTableColumn)[]): void;
    /** 項目の値を変える（default と同じ形で指定。table は選択する行） */
    setValue(name: string, value: unknown): void;
    /**
     * chart の項目のグラフを変える。指定したキーだけが置き換わる（{ data: rows } で行だけ差し替え）。ExcelChart なら丸ごと置き換え。
     * コンソール・mock では表を出力する
     */
    chart(name: string, spec: Partial<ChartSpec> | ExcelChart): void;
    /** ui.withProgress と同じ。進捗をフォーム内に表示し、中止されると onSubmit を終える（onCancel: "break" なら反復が終わるだけ） */
    withProgress<T>(iterable: Iterable<T>, options?: WithProgressOptions<T>): Generator<T, void, undefined>;
    withProgress<T>(iterable: AsyncIterable<T>, options?: WithProgressOptions<T>): AsyncIterableIterator<T>;
  }

  /** 項目の onChange の第 3 引数 */
  interface FormChangeContext {
    /** 項目の値を変える（default と同じ形で指定。table は選択する行）。変えた項目は検証される */
    setValue(name: string, value: unknown): void;
    /** table の項目の行（と列）を入れ替える（選択は解除） */
    table(name: string, rows: readonly unknown[], columns?: (string | FormTableColumn)[]): void;
  }

  interface FormButton<V extends FormValues = FormValues> {
    label: string;
    /** Font Awesome のアイコン（FormField の icon と同じ） */
    icon?: string;
    /** マウスを重ねたときに出す説明（ツールチップ） */
    tooltip?: string;
    /** 押されたときの処理。onSubmit と同じく、出力ファイルを返すと「フォルダを開く」ボタンを出す */
    onClick(values: V, ctx: FormContext): unknown;
    /** false なら検証せずに入力のままの値で実行する（読み込み・クリアなど）。既定 true */
    validate?: boolean;
    /** true なら onClick が正常に終わったらフォームを閉じる（ui.form はその値を返す） */
    close?: boolean;
  }

  interface FormOptions<V extends FormValues = FormValues> {
    /** ウィンドウのタイトル（既定は @title → スクリプト名） */
    title?: string;
    /** 項目の上に出す説明 */
    description?: string;
    /** 項目（tabs があればタブの上に常に表示する項目）。{ group, fields } で見出し付きのグループにまとめられる */
    fields?: (FormField | FormGroup)[];
    /**
     * タブ。各タブの項目はタブを切り替えて表示する（値は fields と同じく 1 つのオブジェクトにまとまるので、名前は全体で重複不可）。
     * コンソールではタブごとに見出しを出して順に尋ねる
     */
    tabs?: { label: string; icon?: string; fields: (FormField | FormGroup)[] }[];
    /** 送信ボタンの文字（既定 "OK"）。false で送信ボタンを出さない（buttons があるときだけ） */
    submit?: string | false;
    /** 送信ボタンの Font Awesome のアイコン（FormField の icon と同じ） */
    submitIcon?: string;
    /** 自前のタイトルバー（titleBar: "custom"）でタイトルの前に出す Font Awesome のアイコン（FormField の icon と同じ）。titleBar が "system" なら無視 */
    icon?: string;
    /**
     * 送信ボタンの左に並べるボタン。押すと onClick を onSubmit と同じように実行する（進捗・ログ・中止。ウィンドウは開いたまま）。
     * コンソールでは項目のあとにどのボタンを押すか尋ねる
     */
    buttons?: FormButton<V>[];
    /**
     * 追加の検証。問題があれば { 項目名: "メッセージ" } か、全体へのメッセージ（文字列）を返す。
     * 項目の検証（required / pattern / min / max / ファイルの存在 / 項目の validate）が通ったあと、送信時だけ呼ばれる。
     * 項目をまたぐ検証に使う（項目の検証は入力中にも行われる）
     */
    validate?(values: V): Record<string, string | null | undefined> | string | null | undefined | void |
      Promise<Record<string, string | null | undefined> | string | null | undefined | void>;
    /**
     * 送信後に実行する処理。ウィンドウは開いたままで、進捗・ログ・中止ボタンを表示する。
     * 出力ファイル（パス・ハンドル、配列可）を返すと完了後に「フォルダを開く」ボタンを出す。
     * ここで起きたエラーはウィンドウに表示される（コンソールでは呼び出し元に伝わる）
     */
    onSubmit?(values: V, ctx: FormContext): unknown;
    /** 前回の値を %APPDATA%\xljs\<スクリプト名>.json に保存して次回の初期値にする */
    remember?: boolean;
    /** remember の保存キー（既定は title）。同じスクリプトで複数のフォームを区別する */
    id?: string;
    /** ウィンドウの大きさ（既定は項目数から決める） */
    width?: number;
    height?: number;
    /** false にするとウィンドウの大きさを固定する（枠のドラッグ・最大化ができない）。既定は true */
    resizable?: boolean;
    /**
     * "custom" にすると OS のタイトルバーを隠し、ページの上端に自前のタイトルバー（icon とタイトル、最小化・最大化・閉じるボタン）を表示する。
     * width / height はタイトルバーを除いた大きさ。既定は "system"（OS のタイトルバー）
     */
    titleBar?: "system" | "custom";
    /**
     * アクセントカラー（送信ボタン・タブ・フォーカス枠・チェックボックス・表の選択行・タイトルバーのアイコン）。
     * "#c42b1c" や "seagreen" のような CSS の色で、ライト・ダークの両方に使う。{ light, dark } で配色ごとに指定できる（省いた側は既定の色）。
     * ボタンの文字色（黒か白）・ホバー色・選択行の色は指定した色から決める。コンソール・モックでは無視
     */
    accent?: string | { light?: string; dark?: string };
  }

  // ------------------------------------------------------------------ ui.table

  interface TableColumn {
    /** 行オブジェクトのキー（配列の行なら位置） */
    key: string | number;
    /** 見出し（既定は key） */
    label?: string;
    /** 列幅（px）。既定は内容から決める */
    width?: number;
  }

  /** フォームの table の列。編集できる列は入力欄になり、入力のたびに検証される */
  interface FormTableColumn extends TableColumn {
    /** この列を編集できるか（既定は項目の editable） */
    editable?: boolean;
    /** 入力欄の種類（既定は値から: 数値は number、Date は date、真偽値は checkbox、ほかは text） */
    type?: "text" | "number" | "date" | "month" | "time" | "select" | "checkbox";
    /** select の選択肢 */
    options?: (string | { value: string; label?: string })[];
    required?: boolean;
    min?: number;
    max?: number;
    step?: number | "any";
    /** 入力全体が一致すべき正規表現（文字列なら全体一致） */
    pattern?: string | RegExp;
    patternMessage?: string;
    /** 追加の検証。問題があればメッセージを返す（row は編集中の行） */
    validate?(value: any, row: any, index: number): string | null | undefined | void | Promise<string | null | undefined | void>;
  }

  interface TableOptions {
    title?: string;
    /**
     * 表示する列と順序。既定はオブジェクトのキー（配列の行なら A, B, C…）。
     * 配列の行に文字列を指定すると、その位置の列の見出しになる
     */
    columns?: (string | TableColumn)[];
    width?: number;
    height?: number;
    /** false にするとウィンドウの大きさを固定する。既定は true */
    resizable?: boolean;
    /**
     * "custom" にすると OS のタイトルバーを隠し、ページの上端に自前のタイトルバー（icon とタイトル、最小化・最大化・閉じるボタン）を表示する。
     * width / height はタイトルバーを除いた大きさ。既定は "system"（OS のタイトルバー）
     */
    titleBar?: "system" | "custom";
    /** 自前のタイトルバーでタイトルの前に出す Font Awesome のアイコン（FormField の icon と同じ）。titleBar が "system" なら無視 */
    icon?: string;
    /**
     * 行（セル）をダブルクリックしたときに呼ばれる。ファイルを開く・メッセージを出すなどに使う。
     * 指定すると selectable: "single" でもダブルクリックで OK にはならない。
     * ネイティブ UI のウィンドウでのみ呼ばれる（コンソール・mock では呼ばれない）
     */
    onDoubleClick?(e: TableDoubleClickEvent): unknown;
  }

  interface TableDoubleClickEvent {
    /** ダブルクリックした行（元のオブジェクト） */
    readonly row: any;
    /** 行の位置（rows の添字） */
    readonly index: number;
    /** ダブルクリックした列の見出し（行番号の欄なら null） */
    readonly column: string | null;
    /** その列のキー（オブジェクトのキーまたは配列の位置） */
    readonly key: string | number | null;
    /** セルの値 */
    readonly value: unknown;
    /** 表のウィンドウを閉じる */
    close(): void;
  }

  interface TableSelectOptions extends TableOptions {
    /** "single"（1 行）/ "multiple" または true（複数行） */
    selectable: "single" | "multiple" | true;
  }

  /** 表示のみの表のウィンドウ */
  interface TableView {
    /** ウィンドウが閉じられると解決する（コンソールではすぐ解決） */
    readonly closed: Promise<void>;
    close(): void;
  }

  // ------------------------------------------------------------------ ui.chart

  /**
   * グラフの種類。column は縦棒、bar は横棒（Excel と同じ呼び方）。gantt はガントチャート（Frappe Gantt）、ほかは AG Charts で描く。
   * Excel のレーダー・株価・等高線、Excel 2016 以降のウォーターフォール・ツリーマップなどは AG Charts Community にないので使えない
   */
  type ChartType = "column" | "bar" | "line" | "area" | "scatter" | "bubble" | "histogram" | "pie" | "donut" | "gantt";

  /**
   * グラフの定義。ui.chart・フォームの chart 項目・画面の xljs.chart で共通。
   * data は行オブジェクト（ui.table や sheet.rows() と同じ形。配列の行なら列は位置）で、列はキー名で指定する。
   * 日付は Date（ローカルの日時）。関数（onClick / onChange 以外）は画面に渡せないので使えない
   */
  interface ChartSpec {
    /** 既定 "column" */
    type?: ChartType;
    data: readonly unknown[];
    title?: string;
    subtitle?: string;
    /** 分類・X 軸の列（既定は先頭の列）。円・ドーナツでは扇の名前 */
    x?: string | number;
    /**
     * 系列の列（文字列なら列名がそのまま凡例の名前）。既定は x 以外の数値の列すべて（円・ドーナツは最初の 1 つ）。
     * { key, type: "line", axis: "y2" } で組み合わせグラフ・第 2 軸
     */
    y?: string | number | ChartSeries | (string | number | ChartSeries)[];
    /** 積み上げ（"percent" は 100% 積み上げ）。column / bar / line / area */
    stacked?: boolean | "percent";
    axes?: { x?: ChartAxis; y?: ChartAxis; y2?: ChartAxis };
    /** 凡例（既定は系列が 2 つ以上か円・ドーナツのとき下に表示） */
    legend?: boolean | "top" | "bottom" | "left" | "right";
    /** 系列の色（既定は Excel と同じ Office のテーマの色）。円・ドーナツでは扇の色 */
    colors?: string[];
    /** 値の表示書式（Excel の書式。"#,##0" "0.0%" "#,##0\"円\"" "yyyy/m/d" など）。軸の目盛り・ツールチップに使う */
    format?: string;
    /** 折れ線の点を表示するか（既定 true） */
    markers?: boolean;
    /** 円・ドーナツの扇の外に名前を出すか（既定 true）。true なら扇の中に値も出す */
    labels?: boolean;
    /** histogram の階級の数 */
    bins?: number;
    // ---- gantt（列の既定はその名前の列。なければ 名前/作業、開始/開始日、終了/終了日、進捗、前提 の列）
    /** 作業名の列（既定 "name"。なければ先頭の列） */
    name?: string | number;
    /** 開始日の列（Date、"2026-04-01"、"2026/4/1 9:00"、Excel のシリアル値） */
    start?: string | number;
    /** 終了日の列。時刻のない日付はその日を含む（4/1〜4/3 は 3 日間）。省略すると開始日の 1 日 */
    end?: string | number;
    /** 進捗の列（0〜100。すべて 0〜1 なら割合とみなす） */
    progress?: string | number;
    /** 前提の作業の列（id 列の値か名前を「,」「、」区切りで。配列も可） */
    dependencies?: string | number;
    /** dependencies が指す id の列 */
    id?: string | number;
    /** 表示の単位（既定 "day"） */
    view?: "day" | "week" | "month" | "year";
    /** 表示の単位を切り替える選択を出すか（既定 true） */
    viewSelect?: boolean;
    /**
     * バーのドラッグで日付（dates）・進捗（progress）を変えられるようにする（true は両方）。
     * 変えた値は元の行に書き込まれ、onChange が呼ばれる
     */
    editable?: boolean | { dates?: boolean; progress?: boolean };
    /** 休日として色を付ける日（Date か "2026-05-03"。{ date, name } なら名前も出す） */
    holidays?: (Date | string | { date: Date | string; name?: string })[];
    /** 土日に色を付けるか（既定 true） */
    weekends?: boolean;
    /** 進捗線・出来高累計曲線の基準日（既定は今日。その日の始まりの位置に縦の線を引く） */
    baseDate?: Date | string;
    /**
     * 進捗線（イナズマ線）を重ねる。基準日の線から、各作業の進捗の位置（開始＋日数×進捗）を上から順に結ぶ。
     * 基準日までに終わった作業と、基準日より後に始まる未着手の作業は基準日の線上の点になる（予定どおり）
     */
    progressLine?: boolean | { color?: string };
    /**
     * 出来高累計曲線（S カーブ）を重ねる。予定は各作業の出来高（weight の列。省略すると日数）を期間に均等に割り振った累計、
     * 実績は actual（その日までの累計の進捗。% か 0〜1）に、基準日の現在の進捗（出来高×進捗の合計）を足した折れ線。
     * 縦の目盛りは 0〜100%（左端に表示）
     */
    sCurve?: boolean | {
      /** 作業ごとの出来高（金額・工数など）の列 */
      weight?: string | number;
      /** 過去の実績（基準日より前の分）。例: [{ date: new Date(2026, 3, 30), value: 12.5 }] */
      actual?: { date: Date | string; value: number }[];
      /** 予定の線の色（既定 "#4472C4"） */
      color?: string;
      /** 実績の線の色（既定 "#ED7D31"） */
      actualColor?: string;
    };
    // ---- 共通
    /** 点・棒・扇・作業がクリックされたとき（row は data の元の要素。series は系列の名前） */
    onClick?(row: any, info: { index: number; series: string | null }): unknown;
    /** ガントチャートで作業の日付・進捗が変えられたとき（row には書き込み済み） */
    onChange?(row: any, changes: { start?: Date; end?: Date; progress?: number }, index: number): unknown;
    /** ライブラリのオプション（AgChartOptions / Frappe Gantt の options）に重ねる値。JSON で表せるもののみ */
    options?: Record<string, unknown>;
  }

  interface ChartSeries {
    /** 値の列 */
    key: string | number;
    /** 凡例の名前（既定は key） */
    label?: string;
    /** この系列だけ種類を変える（組み合わせグラフ） */
    type?: "column" | "bar" | "line" | "area" | "scatter";
    /** "y2" で第 2 軸（右側） */
    axis?: "y" | "y2";
    color?: string;
    /** この系列の値の書式（Excel の書式） */
    format?: string;
    /** bubble の大きさの列 */
    size?: string | number;
  }

  interface ChartAxis {
    title?: string;
    /** 目盛りの書式（Excel の書式） */
    format?: string;
    min?: number | Date;
    max?: number | Date;
    /** 対数目盛り */
    log?: boolean;
  }

  interface ChartWindowOptions {
    /** ウィンドウのタイトル（既定はグラフの title → @title → スクリプト名） */
    title?: string;
    /** クライアント領域の幅・高さ（既定 900 x 560） */
    width?: number;
    height?: number;
    resizable?: boolean;
    titleBar?: "system" | "custom";
    icon?: string;
  }

  /** グラフのウィンドウ */
  interface ChartView {
    /** ウィンドウが閉じられると解決する（コンソールではすぐ解決） */
    readonly closed: Promise<void>;
    close(): void;
    /** グラフを変える。指定したキーだけが置き換わる（{ data: rows } で行だけ差し替え）。ExcelChart なら丸ごと置き換え */
    update(spec: Partial<ChartSpec> | ExcelChart): this;
  }

  /** シート上の Excel のグラフ（sheet.charts）。toSpec() で ChartSpec にする */
  interface ExcelChart {
    readonly sheet: Worksheet;
    /** グラフの名前（"グラフ 1" など） */
    readonly name: string;
    /** 置かれている範囲（"F2:N17"） */
    readonly range: string | null;
    readonly title: string;
    /** 変換後の種類（表示できないグラフなら null） */
    readonly type: ChartType | null;
    /** 表示できるか（レーダー・株価・等高線、Excel 2016 以降の新しい種類は false） */
    readonly supported: boolean;
    /** 変換で省いたもの（3-D・近似曲線など）。表示できないグラフではその理由 */
    readonly warnings: string[];
    /**
     * グラフの定義にする（呼ぶたびに新しい行を作る）。系列の値はセルから読む（読めなければグラフ内のキャッシュ）。
     * 開始日の系列を塗りなしにした積み上げ横棒はガントチャートにする。gantt: true / false で強制・抑止
     */
    toSpec(options?: { gantt?: boolean }): ChartSpec;
  }

  // ------------------------------------------------------------------ app (HTML windows)

  interface AppWindowOptions {
    /** 表示する HTML（スクリプトのフォルダからの相対パス）。@html のファイルか @assets のフォルダ内に置く。省略すると空のページ */
    html?: string;
    /** タイトル。既定は @title → スクリプト名 */
    title?: string;
    /** クライアント領域の幅・高さ（論理ピクセル） */
    width?: number;
    height?: number;
    /** false にするとウィンドウの大きさを固定する（枠のドラッグ・最大化ができない）。既定は true */
    resizable?: boolean;
    /**
     * "custom" にすると OS のタイトルバーを隠し、ページの <body> の先頭に自前のタイトルバー（icon とタイトル、最小化・最大化・閉じるボタン）を差し込む。
     * ページに data-xljs-titlebar 属性の要素があれば差し込まずにそれをタイトルバーにする（ドラッグで移動。中の data-xljs-window="minimize" / "maximize" / "close" のボタンでウィンドウを操作）。
     * width / height はタイトルバー（32px）を除いた大きさ。既定は "system"。メインウィンドウはメタデータの @titlebar custom
     */
    titleBar?: "system" | "custom";
    /** 自前のタイトルバーでタイトルの前に出す Font Awesome のアイコン（"table" や "fa-regular fa-calendar"）。titleBar が "system" なら無視 */
    icon?: string;
  }
  /**
   * 画面との間で受け渡せる値: JSON の値に加えて Date、ファイル/フォルダのハンドル、
   * ArrayBuffer（型付き配列も可）、Error、Map（オブジェクトになる）、Set（配列になる）。
   * 画面で選択・ドロップしたファイル（File）はスクリプト側で FileSystemFileHandle（フォルダをドロップした場合は FileSystemDirectoryHandle）になる
   */
  type WireValue = any;

  /** win.$(selector).on のハンドラが受け取る値（DOM イベントそのものではない） */
  interface AppDomEvent {
    /** "click" など */
    type: string;
    /** イベントが起きた要素（セレクタに一致した要素）の id・name 属性 */
    id: string;
    name: string;
    /** 要素の値（入力欄は値、チェックボックスは true/false、数値入力は number、それ以外は文字列） */
    value: WireValue;
    /** チェックボックス・ラジオボタンの状態 */
    checked?: boolean;
    /** 要素の data-* 属性 */
    dataset: Record<string, string>;
    /** キーボードイベントのキー（"Enter" など） */
    key?: string;
    ctrlKey?: boolean;
    shiftKey?: boolean;
    altKey?: boolean;
    button?: number;
    /** submit（フォーム）のときのフォームの値 */
    values?: Record<string, WireValue>;
    /** drop のときにドロップされたファイル（フォルダは FileSystemDirectoryHandle） */
    files?: (FileSystemFileHandle | FileSystemDirectoryHandle)[];
  }

  /** win.$(selector) が返す要素の集まり。書き込みはすぐ送られ（await 不要）、読み取りは先頭の要素の値を Promise で返す */
  interface AppElements {
    readonly selector: string;
    text(): Promise<string | null>;
    text(value: unknown): this;
    html(): Promise<string | null>;
    html(value: string): this;
    val(): Promise<WireValue>;
    val(value: WireValue): this;
    attr(name: string): Promise<string | null>;
    /** null・false で属性を削除、true で値なしの属性 */
    attr(name: string, value: string | number | boolean | null): this;
    /** 計算済みのスタイル */
    css(name: string): Promise<string>;
    css(name: string, value: string | number | null): this;
    css(styles: Record<string, string | number | null>): this;
    addClass(names: string): this;
    removeClass(names: string): this;
    toggleClass(names: string, force?: boolean): this;
    show(): this;
    hide(): this;
    /** 要素の DOM イベントを受け取る（あとから追加された要素も対象）。submit は常に既定の動作を止める */
    on(type: string, handler: (this: AppWindow, e: AppDomEvent) => unknown, options?: { preventDefault?: boolean }): this;
    /** on で登録したハンドラを外す（type・handler 省略ですべて） */
    off(type?: string, handler?: Function): this;
  }

  /** HTML のウィンドウ（WebView2）。開いている間はプロセスが終了しない */
  interface AppWindow {
    /** ウィンドウが閉じられると解決する */
    readonly closed: Promise<void>;
    /** ウィンドウを閉じる（閉じていれば何もしない） */
    close(): void;
    /**
     * 画面と共有する値。代入すると画面へ送られ、data-bind / data-model の要素に反映される。
     * 画面側（xljs.state、data-model）で変わった値もここに入る。同期するのは最上位のキーだけ
     * （win.state.summary.total = 1 は送られないので win.state.summary = {...} のように代入する）。
     * win.state = {...} は各キーの代入と同じ
     */
    state: Record<string, WireValue>;
    /** 画面の関数（xljs.handle で登録したもの、なければグローバル関数）を呼んで結果を返す */
    invoke<T = any>(name: string, ...args: WireValue[]): Promise<T>;
    /** 画面へイベントを送る（画面側は xljs.on で受け取る） */
    emit(name: string, ...args: WireValue[]): void;
    /** 画面からのイベント（xljs.emit）を受け取る */
    on(name: string, handler: (this: AppWindow, ...args: any[]) => unknown): this;
    /** 画面側で state が変わったとき（key, value） */
    on(name: "state", handler: (this: AppWindow, key: string, value: any) => unknown): this;
    off(name: string, handler?: Function): this;
    /** セレクタに一致する画面の要素（簡易 DOM 操作） */
    $(selector: string): AppElements;
    /**
     * 関数（のソース）を画面で実行して結果を返す。クロージャの変数は使えないので値は引数で渡す。
     * 文字列は式として評価する
     */
    evaluate<A extends any[], R>(fn: (...args: A) => R, ...args: A): Promise<Awaited<R>>;
    evaluate<T = any>(expression: string): Promise<T>;
  }
  interface App {
    /** `@mode app` のメインウィンドウ（スクリプト実行前に自動で開く）。`@mode app` 以外では null */
    readonly main: AppWindow;
    /** ウィンドウを開く。ネイティブ UI（Windows）と WebView2 ランタイムが必要 */
    open(options?: AppWindowOptions | string): AppWindow;
    /**
     * 画面から xljs.invoke(name, ...) で呼べる関数を登録する（null で削除）。
     * エントリファイルの export と同じ扱い（this は呼び出し元のウィンドウ）。export と同じ名前はエラー
     */
    handle(name: string, fn: ((this: AppWindow, ...args: any[]) => unknown) | null): void;
  }
  const app: App;

  // ------------------------------------------------------------------ files

  interface FileSystemHandle {
    readonly kind: "file" | "directory";
    readonly name: string;
    /** 絶対パス（xljs 拡張） */
    readonly path: string;
    /** walk() の起点からの相対パス（xljs 拡張） */
    readonly relativePath: string;
    isSameEntry(other: FileSystemHandle): Promise<boolean>;
    /** 存在するか（xljs 拡張） */
    exists(): boolean;
  }

  interface FileStat {
    isFile: boolean;
    isDirectory: boolean;
    size: number;
    mtimeMs: number;
  }

  type WriteData = string | ArrayBuffer | ArrayBufferView | Blob;

  interface FileSystemWritableFileStream {
    write(data: WriteData | { type: "write"; data: WriteData; position?: number } | { type: "seek"; position: number } | { type: "truncate"; size: number }): Promise<void>;
    seek(position: number): Promise<void>;
    truncate(size: number): Promise<void>;
    close(): Promise<void>;
    abort(): Promise<void>;
  }

  interface FileSystemFileHandle extends FileSystemHandle {
    readonly kind: "file";
    getFile(): Promise<File>;
    createWritable(options?: { keepExistingData?: boolean }): Promise<FileSystemWritableFileStream>;
    // xljs extensions
    stat(): FileStat | null;
    /** 既定 "auto"（BOM / UTF-8 / CP932 を自動判定） */
    readText(encoding?: Encoding): string;
    readBytes(): ArrayBuffer;
    /** 既定 "utf8"（.csv / .tsv は Excel 向けに "utf8bom"） */
    writeText(text: string, encoding?: Encoding): this;
    appendText(text: string, encoding?: Encoding): this;
    writeBytes(data: ArrayBuffer | ArrayBufferView): this;
  }

  interface WalkOptions {
    /** 対象パターン。"/" を含まないパターンは任意の階層のファイル名に一致（大文字小文字無視） */
    glob?: string | string[];
    include?: string | string[];
    /** 除外パターン。フォルダが一致するとその中も除外 */
    exclude?: string | string[];
    /** フォルダも返す（既定 false） */
    directories?: boolean;
    /** ファイルを返す（既定 true） */
    files?: boolean;
    /**
     * 隠しファイル・システムファイル（Windows の属性）、"." で始まる名前、Office のロックファイル（~$*）も返す（既定 false）。
     * false では隠しフォルダの中も走査しない
     */
    hidden?: boolean;
  }
  interface ListOptions {
    /** 隠しファイル・システムファイル、"." で始まる名前、~$* も返す（既定 false） */
    hidden?: boolean;
  }

  interface WalkResult<T extends FileSystemHandle = FileSystemHandle> extends Iterable<T>, AsyncIterable<T> {
    readonly length: number;
    toArray(): T[];
    map<U>(fn: (h: T, i: number) => U): U[];
    filter(fn: (h: T, i: number) => boolean): T[];
    forEach(fn: (h: T, i: number) => void): void;
  }

  interface FileSystemDirectoryHandle extends FileSystemHandle, AsyncIterable<[string, FileSystemHandle]> {
    readonly kind: "directory";
    getFileHandle(name: string, options?: { create?: boolean }): Promise<FileSystemFileHandle>;
    getDirectoryHandle(name: string, options?: { create?: boolean }): Promise<FileSystemDirectoryHandle>;
    removeEntry(name: string, options?: { recursive?: boolean }): Promise<void>;
    resolve(possibleDescendant: FileSystemHandle): Promise<string[] | null>;
    entries(): AsyncIterableIterator<[string, FileSystemFileHandle | FileSystemDirectoryHandle]>;
    keys(): AsyncIterableIterator<string>;
    values(): AsyncIterableIterator<FileSystemFileHandle | FileSystemDirectoryHandle>;
    // xljs extensions
    /** サブフォルダを含めて走査する */
    walk(options?: WalkOptions | string | string[]): WalkResult<FileSystemFileHandle>;
    /** 直下の項目を同期的に列挙する（既定では隠しファイル・システムファイルを除く） */
    list(options?: ListOptions): (FileSystemFileHandle | FileSystemDirectoryHandle)[];
    /** 直下のファイルのハンドル（存在確認なし） */
    file(name: string): FileSystemFileHandle;
    /** 直下のフォルダのハンドル（存在確認なし） */
    dir(name: string): FileSystemDirectoryHandle;
  }

  var FileSystemHandle: { prototype: FileSystemHandle };
  var FileSystemFileHandle: { prototype: FileSystemFileHandle; new (path: string): FileSystemFileHandle };
  var FileSystemDirectoryHandle: { prototype: FileSystemDirectoryHandle; new (path: string): FileSystemDirectoryHandle };

  interface Blob {
    readonly size: number;
    readonly type: string;
    arrayBuffer(): Promise<ArrayBuffer>;
    bytes(): Promise<Uint8Array>;
    /** encoding は xljs 拡張（既定 "utf8"、"auto" で自動判定） */
    text(encoding?: Encoding): Promise<string>;
    slice(start?: number, end?: number, contentType?: string): Blob;
  }
  var Blob: { prototype: Blob; new (parts?: (string | ArrayBuffer | ArrayBufferView | Blob)[], options?: { type?: string }): Blob };

  interface File extends Blob {
    readonly name: string;
    readonly lastModified: number;
    /** ディスク上のパス（xljs 拡張。メモリ上の File では null） */
    readonly path: string | null;
  }
  var File: { prototype: File; new (parts: (string | ArrayBuffer | ArrayBufferView | Blob)[], name: string, options?: { type?: string; lastModified?: number }): File };

  /** 文字列のパスは %USERPROFILE% のような環境変数を展開して使う */
  type PathLike = string | FileSystemHandle | File;

  /**
   * "utf8" / "utf8bom" / "cp932"（= "shift_jis", "sjis"）/ "euc-jp" / "iso-2022-jp" / "utf16le" / "utf16be" / "auto"
   */
  type Encoding = string;

  interface Fs {
    file(path: PathLike): FileSystemFileHandle;
    dir(path: PathLike): FileSystemDirectoryHandle;
    /** 存在しなければ NotFoundError */
    getFileHandle(path: PathLike): Promise<FileSystemFileHandle>;
    getDirectoryHandle(path: PathLike): Promise<FileSystemDirectoryHandle>;
    exists(path: PathLike): boolean;
    isFile(path: PathLike): boolean;
    isDirectory(path: PathLike): boolean;
    stat(path: PathLike): FileStat | null;
    readText(path: PathLike, encoding?: Encoding): string;
    /** 既定 "utf8"（.csv / .tsv は Excel 向けに "utf8bom"） */
    writeText(path: PathLike, text: string, encoding?: Encoding): void;
    appendText(path: PathLike, text: string, encoding?: Encoding): void;
    readBytes(path: PathLike): ArrayBuffer;
    writeBytes(path: PathLike, data: ArrayBuffer | ArrayBufferView | string): void;
    /** JSON ファイルを読む（BOM・CP932 も自動判定） */
    readJSON<T = any>(src: PathLike | Blob, options?: JsonReadOptions): T;
    /** JSON で書き出す。日付は既定でローカル時刻＋オフセット（例 2026-04-01T09:00:00+09:00） */
    writeJSON(dest: PathLike, value: unknown, options?: JsonWriteOptions | number): void;
    /** JSON Lines（1 行 1 JSON）を読む */
    readJSONL<T = any>(src: PathLike | Blob, options?: JsonReadOptions): T[];
    /** 配列を JSON Lines で書き出す */
    writeJSONL(dest: PathLike, rows: Iterable<unknown>, options?: JsonWriteOptions): void;
    /** 直下の名前一覧（既定では隠しファイル・システムファイルを除く） */
    list(path?: PathLike, options?: ListOptions): string[];
    walk(path: PathLike, options?: WalkOptions | string | string[]): WalkResult<FileSystemFileHandle>;
    /** カレントフォルダ（または cwd）からの glob */
    glob(pattern: string, options?: { cwd?: PathLike; exclude?: string | string[]; hidden?: boolean }): FileSystemFileHandle[];
    mkdir(path: PathLike): void;
    remove(path: PathLike, options?: { recursive?: boolean }): void;
    rename(from: PathLike, to: PathLike): void;
    move(from: PathLike, to: PathLike): void;
    copy(from: PathLike, to: PathLike): void;
    cwd(): string;
    chdir(path: PathLike): void;
  }
  const fs: Fs;

  interface JsonReadOptions {
    /** 既定 "auto" */
    encoding?: Encoding;
    /** ISO 形式の日時文字列を Date に戻す（既定 false） */
    dates?: boolean;
  }
  interface JsonWriteOptions {
    /** インデント（既定 2。JSON Lines では無視） */
    space?: number | string;
    /** 既定 "utf8" */
    encoding?: Encoding;
    /** "local"（既定）: 2026-04-01T09:00:00+09:00、"iso": JSON.stringify と同じ UTC 表記 */
    dates?: "local" | "iso";
    /** 追記する（writeJSONL のみ） */
    append?: boolean;
  }

  interface Shell {
    /** エクスプローラーでファイルを選択した状態で表示する（複数可。フォルダが違えばフォルダごとに開く） */
    showItemInFolder(...items: (PathLike | PathLike[])[]): void;
    /** showItemInFolder と同じ */
    showInFolder(...items: (PathLike | PathLike[])[]): void;
    /** ファイル・フォルダを既定のアプリで開く */
    openPath(target: PathLike): void;
    /** URL を既定のブラウザで開く */
    openExternal(url: string): void;
    /** URL なら openExternal、それ以外は openPath */
    open(target: PathLike): void;
  }
  const shell: Shell;

  // ------------------------------------------------------------------ ad (Active Directory)

  /** ad.search / ad.get で使えるオブジェクトの種類。"ou" は "organizationalUnit"、"all" はすべて */
  type ADObjectType = "user" | "computer" | "group" | "contact" | "organizationalUnit" | "ou" | "all";

  /**
   * ディレクトリのオブジェクト。キーは LDAP の属性名（大文字・小文字も同じ）。
   * 日時は Date（なし・無期限は null）、SID・GUID は文字列、複数の値を持つ属性は配列、バイナリは ArrayBuffer。
   * 値のない属性はキーごとない（memberOf などの複数値の属性は []）
   */
  interface ADObject {
    /** 種類: "user" / "computer" / "group" / "contact" / "organizationalUnit"（ほかは objectClass の最後） */
    type: string;
    /** 名前（cn。OU なら ou） */
    name: string;
    /** 識別名（"CN=山田 太郎,OU=営業部,DC=corp,DC=example,DC=com"） */
    distinguishedName: string;
    objectClass: string[];
    objectGUID: string;
    /** "S-1-5-21-..." */
    objectSid?: string;
    /** ログオン名（Windows 2000 より前）。コンピューターは末尾に "$" */
    sAMAccountName?: string;
    /** ユーザー プリンシパル名（"yamada@corp.example.com"） */
    userPrincipalName?: string;
    /** 表示名 */
    displayName?: string;
    /** 名 */
    givenName?: string;
    /** 姓 */
    sn?: string;
    mail?: string;
    /** 部署 */
    department?: string;
    /** 役職 */
    title?: string;
    /** 会社 */
    company?: string;
    description?: string;
    /** 社員番号 */
    employeeID?: string;
    telephoneNumber?: string;
    mobile?: string;
    /** 事業所 */
    physicalDeliveryOfficeName?: string;
    /** 上司の識別名 */
    manager?: string;
    /** 直接所属するグループの識別名（プライマリ グループ「Domain Users」などは含まない） */
    memberOf?: string[];
    userAccountControl?: number;
    /** ロックアウトされた日時（null はロックアウトされていない） */
    lockoutTime?: Date | null;
    /** 最終ログオン（ドメインコントローラー間で同期される値。最大 14 日ほど遅れる） */
    lastLogonTimestamp?: Date | null;
    /** パスワードを最後に変更した日時（null は次回ログオン時に変更が必要） */
    pwdLastSet?: Date | null;
    /** アカウントの有効期限（null は無期限） */
    accountExpires?: Date | null;
    /** 作成日時 */
    whenCreated?: Date;
    /** 更新日時 */
    whenChanged?: Date;
    /** コンピューターの DNS 名 */
    dNSHostName?: string;
    /** コンピューターの OS（"Windows 11 Pro"） */
    operatingSystem?: string;
    operatingSystemVersion?: string;
    groupType?: number;
    /** グループの管理者の識別名 */
    managedBy?: string;
    /** グループのメンバーの識別名（properties: ["member"] を指定したとき） */
    member?: string[];
    /** アカウントが有効か（ユーザー・コンピューター） */
    enabled?: boolean;
    /** ロックアウト中か（ユーザー・コンピューター） */
    lockedOut?: boolean;
    /** パスワードの期限が切れているか（ユーザー・コンピューター） */
    passwordExpired?: boolean;
    /** パスワードを無期限にしているか（ユーザー・コンピューター） */
    passwordNeverExpires?: boolean;
    /** グループのスコープ */
    groupScope?: "domainLocal" | "global" | "universal" | "builtin";
    /** セキュリティ グループか配布グループか */
    groupCategory?: "security" | "distribution";
    /** properties で指定したほかの属性 */
    [attribute: string]: unknown;
  }

  /**
   * filter のオブジェクト形式。属性ごとの条件をすべて満たすものを探す（AND）。
   * 文字列は一致（"*" は任意の文字列）、配列はどれかに一致、true は値がある、false / null は値がない（undefined はエラー）
   */
  type ADFilter = { [attribute: string]: string | number | boolean | null | (string | number)[] };

  interface ADConnectOptions {
    /** 接続するドメインコントローラーまたはドメインの名前（既定はこのコンピューターのドメイン） */
    server?: string;
  }

  interface ADGetOptions extends ADConnectOptions {
    /** 既定の属性に加えて読む属性（"*" ですべて） */
    properties?: string[];
  }

  /** ad.search のオプション。指定した条件をすべて満たすものを探す */
  interface ADSearchOptions extends ADGetOptions {
    /** 種類（既定は "user"。配列でどれか） */
    type?: ADObjectType | ADObjectType[];
    /** 名前・ログオン名・表示名・UPN・メールのどれかに一致（"山田*" のように * が使える） */
    name?: string;
    /** 属性の条件（{ department: "営業部", title: ["課長", "部長"] }）か LDAP のフィルタ（"(title=課長)"）。配列で複数 */
    filter?: ADFilter | string | (ADFilter | string)[];
    /** true で無効なアカウントだけ、false で有効なものだけ（Search-ADAccount -AccountDisabled） */
    disabled?: boolean;
    /** true でロックアウト中のアカウントだけ（Search-ADAccount -LockedOut） */
    lockedOut?: boolean;
    /** true で有効期限切れのアカウントだけ（Search-ADAccount -AccountExpired） */
    expired?: boolean;
    /** 指定の日数以内に有効期限が来るアカウント（Search-ADAccount -AccountExpiring） */
    expiringDays?: number;
    /**
     * 指定の日数ログオンしていないアカウント（一度もログオンしていないものを含む。Search-ADAccount -AccountInactive）。
     * lastLogonTimestamp で判定するので 14 日より短い日数は正確でない
     */
    inactiveDays?: number;
    /** true でパスワードの期限が切れたアカウントだけ（Search-ADAccount -PasswordExpired） */
    passwordExpired?: boolean;
    /** true でパスワード無期限のアカウントだけ（Search-ADAccount -PasswordNeverExpires） */
    passwordNeverExpires?: boolean;
    /** このグループ（名前か識別名）のメンバー */
    memberOf?: string;
    /** memberOf でグループの中のグループのメンバーも含める */
    recursive?: boolean;
    /** 検索する場所（OU などの識別名。既定はドメイン全体） */
    searchBase?: string;
    /** searchBase からの範囲（既定 "subtree"＝配下すべて、"onelevel"＝直下だけ、"base"＝それ自身） */
    scope?: "subtree" | "onelevel" | "base";
    /** 最大件数（既定は無制限） */
    limit?: number;
  }

  /**
   * Active Directory（Windows のみ）。サインイン中のユーザーの権限で、このコンピューターのドメインを検索する。
   * PowerShell の Get-ADUser / Get-ADComputer / Get-ADGroup / Search-ADAccount に当たるものを ad.search 1 つで行う
   */
  interface AD {
    /** このコンピューターがドメインに参加しているか（ドメインには問い合わせない） */
    available(): boolean;
    /** ドメインの情報 */
    domain(options?: ADConnectOptions): {
      /** DNS 名（"corp.example.com"） */
      name: string;
      /** NetBIOS 名（"CORP"。読めなければ null） */
      netbiosName: string | null;
      distinguishedName: string;
      /** フォレストのルートドメインの DNS 名 */
      forest: string;
      /** 接続したドメインコントローラー */
      server: string;
    };
    /** サインイン中のユーザー（ドメインのアカウントでなければエラー） */
    me(options?: ADGetOptions): ADObject;
    /** このコンピューター */
    computer(options?: ADGetOptions): ADObject;
    /**
     * 1 件取得する。identity は識別名・ログオン名（"CORP\\yamada" も可。コンピューターは "$" なしでも可）・
     * UPN・メールアドレス・SID・GUID・名前のどれか。見つからなければ null
     */
    get(identity: string, options?: ADGetOptions & { type?: ADObjectType | ADObjectType[] }): ADObject | null;
    /** 検索する（文字列なら name での検索）。条件がなければ全ユーザー */
    search(options?: ADSearchOptions | string): ADObject[];
  }
  const ad: AD;

  interface Path {
    readonly sep: string;
    join(...parts: PathLike[]): string;
    resolve(...parts: PathLike[]): string;
    dirname(p: PathLike): string;
    basename(p: PathLike, ext?: string): string;
    extname(p: PathLike): string;
    normalize(p: PathLike): string;
    isAbsolute(p: PathLike): boolean;
    relative(from: PathLike, to: PathLike): string;
    /**
     * 文字列中の %NAME% を環境変数の値に置き換える（未定義の変数はそのまま）。
     * パスを受け取る API はすべて自動で展開するので、表示用などに使う。例 path.expandEnv("%USERPROFILE%\\Desktop")
     */
    expandEnv(s: string): string;
  }
  const path: Path;

  // ------------------------------------------------------------------ csv

  interface CsvParseOptions {
    /** 1 行目を見出しとしてオブジェクトにする（既定 true） */
    header?: boolean;
    delimiter?: string;
    /** header: false のときの列名 */
    columns?: string[];
    /**
     * 値の変換（既定 true）: 数値（"1,234" も可。先頭が 0 のコードや 16 桁以上は文字列のまま）、
     * 日付（2026/4/1、2026-04-01 09:30 → Date）、TRUE/FALSE、空欄は null。false ですべて文字列
     */
    cast?: boolean;
    trim?: boolean;
    skipEmptyLines?: boolean;
    comment?: string;
  }
  interface CsvReadOptions extends CsvParseOptions {
    /** 既定 "auto" */
    encoding?: Encoding;
  }
  interface CsvStringifyOptions {
    header?: boolean;
    columns?: string[];
    delimiter?: string;
    /** 既定 "\r\n" */
    eol?: "\r\n" | "\n";
    quoteAll?: boolean;
  }
  interface CsvWriteOptions extends CsvStringifyOptions {
    /** 既定 "utf8bom"（Excel で文字化けしない） */
    encoding?: Encoding;
    append?: boolean;
  }
  interface Row {
    [column: string]: any;
  }
  interface Csv {
    parse(text: string, options?: CsvParseOptions & { header?: true }): Row[];
    parse(text: string, options: CsvParseOptions & { header: false }): CellValue[][];
    stringify(rows: Row[] | unknown[][], options?: CsvStringifyOptions): string;
    read(src: PathLike | Blob, options?: CsvReadOptions & { header?: true }): Row[];
    read(src: PathLike | Blob, options: CsvReadOptions & { header: false }): CellValue[][];
    write(dest: PathLike, rows: Row[] | unknown[][], options?: CsvWriteOptions): void;
  }
  const csv: Csv;

  // ------------------------------------------------------------------ workbooks

  type CellValue = number | string | boolean | Date | null;

  /** "#RRGGBB" / "#RGB" / "RRGGBB" または red, white, gray などの色名 */
  type Color = string;

  type BorderStyleName = "none" | "thin" | "medium" | "dashed" | "dotted" | "thick" | "double" | "hair" |
    "mediumDashed" | "dashDot" | "mediumDashDot" | "dashDotDot" | "mediumDashDotDot" | "slantDashDot";
  /** "thin" などの線種、{ style, color }、true（細線）、null（線なし） */
  type BorderSide = BorderStyleName | { style?: BorderStyleName; color?: Color } | boolean | null;

  interface BorderSpec {
    /** 範囲内のすべてのセルの上下左右 */
    all?: BorderSide;
    /** 範囲の外枠 */
    outline?: BorderSide;
    /** 範囲の内側の線（縦横） */
    inside?: BorderSide;
    /** 内側の横線 */
    horizontal?: BorderSide;
    /** 内側の縦線 */
    vertical?: BorderSide;
    top?: BorderSide;
    bottom?: BorderSide;
    left?: BorderSide;
    right?: BorderSide;
    diagonalUp?: BorderSide;
    diagonalDown?: BorderSide;
  }

  interface FontSpec {
    name?: string;
    size?: number;
    bold?: boolean;
    italic?: boolean;
    /** true / "single" / "double" / "none" */
    underline?: boolean | "single" | "double" | "singleAccounting" | "doubleAccounting" | "none";
    strike?: boolean;
    color?: Color;
    vertAlign?: "superscript" | "subscript" | "baseline";
  }

  interface AlignmentSpec {
    horizontal?: "general" | "left" | "center" | "right" | "fill" | "justify" | "centerContinuous" | "distributed";
    vertical?: "top" | "center" | "middle" | "bottom" | "justify" | "distributed";
    /** 折り返して全体を表示 */
    wrap?: boolean;
    /** 縮小して全体を表示 */
    shrink?: boolean;
    indent?: number;
    /** 文字の角度（-90〜90、255 で縦書き） */
    rotation?: number;
  }

  /**
   * セルの書式。指定した項目だけが既存の書式に上書きされる。
   * 省略形: bold, italic, underline, strike, color（文字色）, fontSize, fontName,
   * background（= fill）, align, valign, wrap, format（= numberFormat）
   */
  interface CellStyle {
    font?: FontSpec;
    /** 塗りつぶしの色。null または "none" で塗りなし */
    fill?: Color | { color: Color } | null;
    /** "thin" などで全セルの上下左右、または辺ごとの指定 */
    border?: BorderSide | BorderSpec;
    alignment?: AlignmentSpec;
    /** "#,##0"、"yyyy/m/d"、"0.0%" などの表示形式、または組み込み番号。"General" で標準に戻す */
    numberFormat?: string | number;
    protection?: { locked?: boolean };
    bold?: boolean;
    italic?: boolean;
    underline?: FontSpec["underline"];
    strike?: boolean;
    color?: Color;
    fontSize?: number;
    fontName?: string;
    background?: Color | null;
    align?: AlignmentSpec["horizontal"];
    valign?: AlignmentSpec["vertical"];
    wrap?: boolean;
    format?: string | number;
  }

  interface StyleOptions {
    /** 既存の書式を消してから適用する（既定 false: 既存の書式にマージ） */
    replace?: boolean;
  }

  interface Range {
    readonly address: string;
    readonly sheet: Worksheet;
    style(style: CellStyle, options?: StyleOptions): this;
    font(font: FontSpec): this;
    fill(color: Color | null): this;
    border(border: BorderSide | BorderSpec): this;
    align(horizontal?: AlignmentSpec["horizontal"], vertical?: AlignmentSpec["vertical"]): this;
    numberFormat(format: string | number): this;
    merge(): this;
    unmerge(): this;
    /** 範囲の値（2 次元配列）。代入すると左上から書き込む */
    values: CellValue[][];
  }

  interface Cell {
    readonly address: string;
    readonly row: number;
    readonly column: number;
    /** 型付きの値（数値・文字列・真偽値・日付・空欄は null） */
    value: CellValue;
    /** 表示形式を適用した文字列 */
    readonly text: string;
    /** "=SUM(A1:A3)" のような数式。なければ null */
    formula: string | null;
    /** 数式を計算する（対応関数は一部） */
    calc(): string;
    /** 書式を適用する（既存の書式にマージ） */
    style(style: CellStyle, options?: StyleOptions): this;
    /** 現在の書式（style() に渡せる形） */
    getStyle(): CellStyle;
  }

  interface ToObjectsOptions {
    /** 見出し行の行番号（既定 1）。0 で見出しなし（columns を指定） */
    header?: number;
    columns?: string[];
    /** 空行を除く（既定 true） */
    skipEmpty?: boolean;
    /** 表示形式を適用した文字列で返す */
    text?: boolean;
  }
  interface WriteOptions {
    /** 書き込み開始セル（既定 "A1"） */
    start?: string;
    /** オブジェクト配列のとき見出し行を書く（既定 true） */
    header?: boolean;
    columns?: string[];
    /** 見出し行の書式 */
    headerStyle?: CellStyle;
    /** 書き込んだ範囲全体の書式 */
    style?: CellStyle;
    /** 列ごとの書式（キーは列名・列番号 0〜・列記号 "C"）。見出しを除くデータ部分に適用 */
    columnStyles?: Record<string, CellStyle>;
    /** 表の体裁にする: 見出しの太字・塗り・罫線、データの罫線、列幅自動調整、見出し行の固定、フィルター。
     * { header, body } で書式を差し替えられる */
    table?: boolean | { header?: CellStyle; body?: CellStyle };
    /** 列幅を自動調整（table では既定 true） */
    autoFit?: boolean;
    /** 見出し行の下でウィンドウ枠を固定（table では既定 true） */
    freeze?: boolean;
    /** 見出し行にフィルターを付ける（table では既定 true） */
    filter?: boolean;
  }

  interface Worksheet {
    readonly book: Workbook;
    name: string;
    cell(address: string): Cell;
    cell(row: number, column: number): Cell;
    getValue(address: string): CellValue;
    getValue(row: number, column: number): CellValue;
    setValue(address: string, value: unknown): this;
    setValue(row: number, column: number, value: unknown): this;
    toArrays(options?: { text?: boolean; skipEmpty?: boolean }): CellValue[][];
    toObjects<T = Row>(options?: ToObjectsOptions): T[];
    rows<T = Row>(options?: ToObjectsOptions): T[];
    write(rows: Row[] | unknown[][], options?: WriteOptions): this;
    /** 最終行の下に追記する */
    append(rows: Row[] | unknown[][], options?: WriteOptions): this;
    /** 使用範囲（例 "A1:D20"） */
    readonly dimension: string;
    /** シート上の Excel のグラフ（開いたときのファイルにあったもの。値は読んだ時点のセルから） */
    readonly charts: ExcelChart[];
    readonly rowCount: number;
    /** setColumnWidth("A", 20) / setColumnWidth("A:C", 12) */
    setColumnWidth(columns: string, width: number): this;
    getColumnWidth(column: string): number;
    setRowHeight(row: number, height: number): this;
    /** 内容に合わせて列幅を調整する（省略時は全列）。全角文字は 2 文字分として計算 */
    autoFit(columns?: string, options?: { min?: number; max?: number }): this;
    autoFit(options: { min?: number; max?: number }): this;
    /** range("A1:D10") */
    range(address: string): Range;
    /** style("A1:D1", { bold: true, background: "#DDEBF7", border: "thin" }) */
    style(address: string, style: CellStyle, options?: StyleOptions): this;
    merge(address: string): this;
    unmerge(address: string): this;
    /** 指定セルより上の行・左の列を固定する（freeze("A2") で 1 行目を固定）。{ rows, columns } でも指定可 */
    freeze(cell: string | { rows?: number; columns?: number }): this;
    unfreeze(): this;
    /** フィルターを付ける（既定: 使用範囲） */
    autoFilter(address?: string): this;
    /**
     * Excel で印刷したときのように PDF に書き出す（WebView2 が必要。Windows のネイティブ UI のみ）。
     * 用紙・向き・余白・拡大縮小・印刷範囲・印刷タイトル・改ページ・ヘッダー/フッターはシートのページ設定に従い、options で上書きできる。
     * 画像・図形・テキストボックス・線（よく使う形。ほかの形は四角になる）とグラフ（sheet.charts で描けるもの）も描く。書き出したファイルの絶対パスを返す
     */
    toPdf(dest: PathLike, options?: PrintOptions): Promise<string>;
    /** 印刷したときのページを HTML 文書にする（グラフは空の枠。ブラウザで開くとページの区切りが見える） */
    toHtml(options?: PrintOptions): string;
  }

  /** toPdf / toHtml のオプション。省略した項目はシートのページ設定に従う */
  interface PrintOptions {
    /** 書き出すシート（名前・番号・Worksheet。workbook.toPdf のみ。既定: 非表示でないすべてのシート） */
    sheets?: (string | number | Worksheet)[];
    /** 用紙: "A3" "A4" "A5" "B4" "B5"（JIS）"Letter" "Legal" など */
    paper?: string;
    /** 横向き */
    landscape?: boolean;
    /** 拡大縮小（%、10〜400） */
    scale?: number;
    /** 横 n ページに収める（true は 1）。fitToHeight を省くと縦は自動 */
    fitToWidth?: number | boolean;
    /** 縦 n ページに収める（true は 1）。fitToWidth を省くと横は自動 */
    fitToHeight?: number | boolean;
    /** 1 ページに収める */
    fitToPage?: boolean;
    /** 余白（mm）。数値なら上下左右とも */
    margin?: number | { top?: number; right?: number; bottom?: number; left?: number };
    /** 枠線（セルの境界の薄い線）を印刷する */
    gridLines?: boolean;
    /** ページの左右中央に配置する */
    centerHorizontally?: boolean;
    /** false でグラフを描かない */
    charts?: boolean;
    /** PDF の文書のタイトル（既定: ファイル名） */
    title?: string;
  }

  /** xljs.htmlToPdf のオプション。HTML に @page があればそちらが優先 */
  interface HtmlPdfOptions {
    /** 用紙（CSS の size の名前: "A4" "A3" "A5" "B4" "B5" "letter" "legal"。既定 "A4"） */
    paper?: string;
    landscape?: boolean;
    /** 余白（mm、既定 15） */
    margin?: number | { top?: number; right?: number; bottom?: number; left?: number };
  }

  interface Workbook {
    readonly path: string | null;
    readonly sheetNames: string[];
    /** シート一覧。book.sheets["売上"] のように名前でも参照できる（大文字小文字・前後の空白・全角半角の違いは、該当が 1 つなら許す） */
    readonly sheets: Worksheet[] & { [name: string]: Worksheet | undefined };
    sheet(nameOrIndex: string | number): Worksheet | null;
    addSheet(name: string): Worksheet;
    removeSheet(sheet: string | Worksheet): void;
    /** 保存。省略時は開いたファイルに上書き */
    save(dest?: PathLike): this;
    toArrayBuffer(): ArrayBuffer;
    toBlob(): Blob;
    /** シート（既定: 非表示でないすべて。options.sheets で指定）を Excel で印刷したときのように 1 つの PDF に書き出す。詳しくは Worksheet.toPdf */
    toPdf(dest: PathLike, options?: PrintOptions): Promise<string>;
    /** 印刷したときのページを HTML 文書にする（グラフは空の枠） */
    toHtml(options?: PrintOptions): string;
    close(): void;
    /** ブックの既定フォント */
    readonly defaultFont: { name: string; size: number };
  }

  interface VBAModule {
    name: string;
    /** standard = 標準モジュール、document = ThisWorkbook とシートのモジュール、form = ユーザーフォーム（コードのみ） */
    type: "standard" | "class" | "document" | "form";
    /** ソース（改行は \n。先頭の Attribute 行も含む） */
    code: string;
    /** シートのモジュールのシート名（.xlsm などで分かる場合。それ以外は null） */
    sheet: string | null;
  }

  interface VBAProject {
    /** プロジェクト名（通常 "VBAProject"） */
    name: string;
    /** ソースの文字コード（日本語の Excel では 932） */
    codePage: number;
    modules: VBAModule[];
    /** 全モジュールを 1 つにまとめた Markdown（xljs vba の出力と同じ。AI チャットに貼る用） */
    text: string;
  }

  interface Workbooks {
    /** .xlsx を開く（パス・ハンドル・File・Blob・ArrayBuffer） */
    open(src: PathLike | Blob | ArrayBuffer | ArrayBufferView): Workbook;
    /**
     * マクロブック（.xlsm / .xlsb / .xlam / .xltm）の VBA コードを、ブックを開かずに読む。
     * マクロがなければ null。xlsx でない形式・読み取りパスワード付きのブックは例外
     */
    readVBA(src: PathLike | Blob | ArrayBuffer | ArrayBufferView): VBAProject | null;
    /** 新しいブックを作る（最初の addSheet が既定シートを置き換える）。
     * 既定フォントは表示言語に合わせる（日本語では游ゴシック）。font で変更可 */
    create(options?: { font?: string }): Workbook;
    /** 1 → "A" */
    columnName(n: number): string;
    /** (行, 列) → "B3" */
    cellName(row: number, column: number): string;
  }
  const workbooks: Workbooks;

  // ------------------------------------------------------------------ pdf

  /** PDF の入力: パス・ハンドル・File・Blob・ArrayBuffer・バイト列 */
  type PdfSource = PathLike | Blob | ArrayBuffer | ArrayBufferView;

  /**
   * ページの指定（1 始まり）: 番号、番号の配列、"1-3,5" のような文字列、"all"（すべて）。
   * 負の番号は後ろから（-1 = 最後のページ）。"3-" は 3 ページ目から最後まで、"5-3" は逆順
   */
  type PdfPages = number | (number | string)[] | string;

  interface PdfPageInfo {
    /** ページ番号（1 始まり） */
    number: number;
    /** 表示したときの幅（mm。回転後） */
    width: number;
    /** 表示したときの高さ（mm。回転後） */
    height: number;
    /** 回転（時計回り。0 / 90 / 180 / 270） */
    rotation: number;
  }

  interface PdfInsertOptions {
    /** 取り込むページ（既定: すべて。並べた順に入る） */
    pages?: PdfPages;
    /** 取り込む PDF のパスワード */
    password?: string;
  }

  interface PdfBlankPageOptions {
    /** 用紙: "A3" "A4" "A5" "B4" "B5"（JIS）"Letter" "Legal" など（既定: 隣のページと同じ大きさ。ページがなければ A4） */
    paper?: string;
    /** 横向き */
    landscape?: boolean;
    /** 幅（mm） */
    width?: number;
    /** 高さ（mm） */
    height?: number;
  }

  /**
   * addText の置き場所。ページの四隅・上下の中央・中央から margin（mm）だけ内側に置く。
   * 日本語の "左上" "上中央" "右上" "左下" "下中央" "右下" "中央"、"bottomRight" "bottom"（= 下中央）なども使える
   */
  type PdfTextPosition =
    | "top-left" | "top-center" | "top-right"
    | "center-left" | "center" | "center-right"
    | "bottom-left" | "bottom-center" | "bottom-right"
    | "左上" | "上中央" | "右上" | "左" | "中央" | "右" | "左下" | "下中央" | "右下"
    | (string & {});

  /**
   * addText のオプション。位置は position（四隅・中央など）で指定するのが簡単。細かく決めるときは
   * x / y / right / bottom（表示したときのページの端からの mm。回転したページでも見た目の向き）
   */
  interface PdfTextOptions {
    /** 置き場所（例: ページ番号は "bottom-center"、資料番号は "top-right"）。x / y / right / bottom を指定した向きはそちらが優先 */
    position?: PdfTextPosition;
    /** position で置くときのページの端からの距離（mm。既定 10）。{ x: 横, y: 縦 } で別々に */
    margin?: number | { x?: number; y?: number };
    /** 左端からの位置（mm）。align が "center" なら中央、"right" なら右端の位置。省略時は align に応じてページの左端・中央・右端 */
    x?: number;
    /** 上端から文字の上端までの位置（mm。既定 0） */
    y?: number;
    /** x の代わりに右端からの位置（mm。文字の右端） */
    right?: number;
    /** y の代わりに下端からの位置（mm。最後の行の下端） */
    bottom?: number;
    /** 文字の大きさ（pt。既定 11） */
    size?: number;
    /** 色: "#rrggbb" "#rgb" か black / white / red / green / blue / yellow / orange / purple / gray / silver / navy（既定 black） */
    color?: string;
    /** 不透明度（0〜1。透かしには 0.2〜0.3 くらい） */
    opacity?: number;
    /** 複数行のときの行の揃え（既定: position の左右に合わせる。x だけのときは x が左端・中央・右端のどれかも決める） */
    align?: "left" | "center" | "right";
    /** 行の間隔（文字の大きさの倍数。既定 1.3） */
    lineHeight?: number;
    /** 回転（度。反時計回り。置き場所の点（position なら角・中央、x / y なら文字の上端）が中心） */
    rotate?: number;
    /**
     * フォント: 名前（"游ゴシック" "メイリオ" "ＭＳ 明朝" "Arial" など）かフォントファイルのパス（.ttf .ttc .otf）。
     * 配列なら文字ごとに前から順に探す。既定は言語の Excel のフォント（日本語は游ゴシック）と OS の標準のフォント。
     * 使った文字だけを PDF に埋め込む
     */
    font?: string | FileSystemFileHandle | (string | FileSystemFileHandle)[];
  }

  /** addText の文字を返す関数に渡すページの情報 */
  interface PdfTextPage {
    /** ページ番号（1 始まり） */
    number: number;
    /** 全ページ数 */
    count: number;
    /** 幅（mm） */
    width: number;
    /** 高さ（mm） */
    height: number;
  }

  /** 開いている PDF。変更は save() するまでファイルに書かれない。メソッドは this を返すのでつなげて書ける */
  interface PdfDocument {
    /** 開いたファイル・最後に保存したファイルのパス（新しい文書は null） */
    readonly path: string | null;
    readonly pageCount: number;
    /** ページの大きさと回転 */
    readonly pages: PdfPageInfo[];
    /** src のページを最後に足す（結合）。src は別の PdfDocument か PDF ファイル */
    append(src: PdfDocument | PdfSource, options?: PdfInsertOptions): this;
    /** src のページを at ページ目の前に挿入する（at = pageCount + 1 で最後）。src に自分自身を渡すとページの複製 */
    insert(at: number, src: PdfDocument | PdfSource, options?: PdfInsertOptions): this;
    /** 白紙のページを at ページ目の前に挿入する（at を省くと最後） */
    insertBlankPage(at?: number, options?: PdfBlankPageOptions): this;
    insertBlankPage(options: PdfBlankPageOptions): this;
    /** ページを削除する */
    removePages(pages: PdfPages): this;
    /** ページを時計回りに回転する（angle は 90 の倍数。-90 で反時計回り） */
    rotatePages(pages: PdfPages, angle: number): this;
    /**
     * ページに文字を書く（"\n" で改行）。text を関数にするとページごとに呼ばれる（ページ番号など）。
     * 例: doc.addText("all", (p) => `${p.number} / ${p.count}`, { position: "bottom-center" })
     *     doc.addText("all", "資料番号 A-001", { position: "top-right", size: 9 })
     */
    addText(pages: PdfPages, text: string | ((page: PdfTextPage) => string), options?: PdfTextOptions): this;
    /** 保存。省略時は開いたファイルに上書き。保存した PDF は暗号化しない */
    save(dest?: PathLike): this;
    toArrayBuffer(): ArrayBuffer;
    toBlob(): Blob;
    close(): void;
  }

  interface Pdf {
    /** PDF を開く（パスワード付きの PDF は options.password） */
    open(src: PdfSource, options?: { password?: string }): PdfDocument;
    /** ページのない新しい文書 */
    create(): PdfDocument;
    /** PDF を 1 つにまとめる。dest を指定すると保存してその絶対パスを返し、省くと文書を返す */
    merge(sources: (PdfDocument | PdfSource)[], dest: PathLike): string;
    merge(sources: (PdfDocument | PdfSource)[]): PdfDocument;
    PdfDocument: Function;
  }
  /** PDF の編集（結合・ページの削除・挿入・回転・文字の追加）。Excel・WebView2 は不要 */
  const pdf: Pdf;

  // ------------------------------------------------------------------ dayjs

  /**
   * Day.js（https://day.js.org/）。組み込み済みで、日本語ロケールとプラグイン
   * （customParseFormat, isBetween, isSameOrAfter, isSameOrBefore, minMax, quarterOfYear,
   * weekOfYear, isoWeek, dayOfYear, duration, relativeTime, advancedFormat, isLeapYear,
   * isToday, isTomorrow, isYesterday, weekday, localeData）を読み込み済み。
   * "2026-04-01" や "2026/4/1" はローカル時刻の 0 時として読む。
   * Dayjs のオブジェクトは Date と同じようにセル・CSV・JSON・表・フォームに渡せる。
   */
  type DayjsInput = Dayjs | Date | string | number | null | undefined;
  type DayjsUnit = "millisecond" | "second" | "minute" | "hour" | "day" | "week" | "month" | "quarter" | "year" | "date" |
    "ms" | "s" | "m" | "h" | "d" | "w" | "M" | "Q" | "y" | "isoWeek" |
    "milliseconds" | "seconds" | "minutes" | "hours" | "days" | "weeks" | "months" | "quarters" | "years";
  interface Dayjs {
    /** "YYYY-MM-DD"、"YYYY年M月D日(ddd)"、"HH:mm:ss" など */
    format(template?: string): string;
    isValid(): boolean;
    toDate(): Date;
    /** UTC の ISO 形式（JSON.stringify と同じ） */
    toISOString(): string;
    toJSON(): string;
    valueOf(): number;
    unix(): number;
    clone(): Dayjs;
    year(): number; year(value: number): Dayjs;
    /** 月（0〜11） */
    month(): number; month(value: number): Dayjs;
    /** 日（1〜31） */
    date(): number; date(value: number): Dayjs;
    /** 曜日（0 = 日曜） */
    day(): number; day(value: number): Dayjs;
    hour(): number; hour(value: number): Dayjs;
    minute(): number; minute(value: number): Dayjs;
    second(): number; second(value: number): Dayjs;
    millisecond(): number; millisecond(value: number): Dayjs;
    get(unit: DayjsUnit): number;
    set(unit: DayjsUnit, value: number): Dayjs;
    add(value: number, unit?: DayjsUnit): Dayjs;
    subtract(value: number, unit?: DayjsUnit): Dayjs;
    startOf(unit: DayjsUnit): Dayjs;
    endOf(unit: DayjsUnit): Dayjs;
    /** 差（this - other）。float: true で小数 */
    diff(other?: DayjsInput, unit?: DayjsUnit, float?: boolean): number;
    daysInMonth(): number;
    isBefore(other?: DayjsInput, unit?: DayjsUnit): boolean;
    isAfter(other?: DayjsInput, unit?: DayjsUnit): boolean;
    isSame(other?: DayjsInput, unit?: DayjsUnit): boolean;
    isSameOrBefore(other?: DayjsInput, unit?: DayjsUnit): boolean;
    isSameOrAfter(other?: DayjsInput, unit?: DayjsUnit): boolean;
    /** inclusivity: "()"（既定）"[]" "[)" "(]" */
    isBetween(a: DayjsInput, b: DayjsInput, unit?: DayjsUnit | null, inclusivity?: "()" | "[]" | "[)" | "(]"): boolean;
    quarter(): number; quarter(value: number): Dayjs;
    week(): number; week(value: number): Dayjs;
    isoWeek(): number; isoWeek(value: number): Dayjs;
    isoWeekday(): number; isoWeekday(value: number): Dayjs;
    isoWeekYear(): number;
    dayOfYear(): number; dayOfYear(value: number): Dayjs;
    weekday(): number; weekday(value: number): Dayjs;
    isLeapYear(): boolean;
    isToday(): boolean;
    isTomorrow(): boolean;
    isYesterday(): boolean;
    /** "3日前" など */
    from(other: DayjsInput, withoutSuffix?: boolean): string;
    to(other: DayjsInput, withoutSuffix?: boolean): string;
    fromNow(withoutSuffix?: boolean): string;
    toNow(withoutSuffix?: boolean): string;
    locale(): string; locale(name: string): Dayjs;
  }
  interface DayjsDuration {
    format(template?: string): string;
    asMilliseconds(): number; asSeconds(): number; asMinutes(): number; asHours(): number; asDays(): number; asMonths(): number; asYears(): number;
    milliseconds(): number; seconds(): number; minutes(): number; hours(): number; days(): number; months(): number; years(): number;
    add(value: number | DayjsDuration, unit?: DayjsUnit): DayjsDuration;
    subtract(value: number | DayjsDuration, unit?: DayjsUnit): DayjsDuration;
    humanize(withSuffix?: boolean): string;
    toISOString(): string;
  }
  interface DayjsStatic {
    /** 引数なしで現在時刻。format を渡すとその形式で読む（strict: true で厳密に） */
    (date?: DayjsInput, format?: string | string[], strict?: boolean): Dayjs;
    (date: DayjsInput, format: string | string[], locale: string, strict?: boolean): Dayjs;
    isDayjs(value: unknown): value is Dayjs;
    unix(seconds: number): Dayjs;
    max(...dates: Dayjs[]): Dayjs | null;
    max(dates: Dayjs[]): Dayjs | null;
    min(...dates: Dayjs[]): Dayjs | null;
    min(dates: Dayjs[]): Dayjs | null;
    duration(value: number, unit?: DayjsUnit): DayjsDuration;
    duration(value: Partial<Record<"milliseconds" | "seconds" | "minutes" | "hours" | "days" | "weeks" | "months" | "years", number>>): DayjsDuration;
    /** 既定 "ja"。"en" で英語 */
    locale(name?: string): string;
    extend(plugin: unknown, option?: unknown): DayjsStatic;
    /** Excel の日付のシリアル値（日付の書式がないセルの数値）を日時にする（xljs 拡張） */
    fromExcel(serial: number): Dayjs;
  }
  const dayjs: DayjsStatic;

  interface ObjectConstructor {
    groupBy<K extends PropertyKey, T>(items: Iterable<T>, keySelector: (item: T, index: number) => K): Partial<Record<K, T[]>>;
  }
  interface ArrayConstructor {
    fromAsync<T, U = T>(iterable: AsyncIterable<T> | Iterable<T | PromiseLike<T>>, mapFn?: (value: T, index: number) => U): Promise<U[]>;
  }
}
